function buildFrontMatter(type, date) {
  return [
    '---',
    `type: ${type || 'note'}`,
    date ? `date: ${date}` : 'date:',
    'tags:',
    '  - plaud',
    'date_reviewed:',
    '---',
    '',
    '',
  ].join('\n');
}

// Change this node name if your upstream preparation node has a different name
const upstream = $('Rewrite URLs').item.json;

const fileName = String(upstream.desiredFileName || 'output.md');
const targetDir = String(upstream.targetDir || '/data/applaud');
const filePath = `${targetDir}/${fileName}`;

if (upstream.kind === 'downloadedImage') {
  const binary = $binary.data
    ? { ...$binary.data, fileName, mimeType: 'image/png' }
    : await this.helpers.prepareBinaryData(
        Buffer.from($json.data || '', 'binary'),
        fileName,
        'image/png'
      );

  return {
    json: {
      targetDir,
      desiredFileName: fileName,
      targetPath: filePath,
      vaultDir: upstream.vaultDir || '',
      vaultRelinkImages: upstream.vaultRelinkImages === true,
    },
    binary: { data: binary },
  };
}

let content =
  typeof $json.data === 'string'
    ? $json.data
    : (typeof $json.body === 'string'
        ? $json.body
        : (typeof $json.content === 'string' ? $json.content : ''));

if (!content) {
  throw new Error(`Downloaded markdown content was empty for ${fileName}; refusing to upload a blank file.`);
}

for (const rewrite of upstream.markdownImageRewrites || []) {
  if (!rewrite.source || !rewrite.replacement) continue;
  content = content.split(rewrite.source).join(rewrite.replacement);
}

content = content.replace(/\r\n/g, '\n');

// Summary only: a text line directly followed by a line of dashes renders as a
// heading in Markdown. Insert a blank line so the dashes become a divider.
if (upstream.fixDividerSpacing) {
  content = content.replace(/^([^\n]*\S[^\n]*)\n([ \t]*-{3,}[ \t]*)$/gm, '$1\n\n$2');
}

content = buildFrontMatter(upstream.frontMatterType, upstream.recordingDate) + content;

return {
  json: {
    targetDir,
    desiredFileName: fileName,
    targetPath: filePath,
    vaultDir: upstream.vaultDir || '',
    vaultRelinkImages: upstream.vaultRelinkImages === true,
  },
  binary: {
    data: await this.helpers.prepareBinaryData(
      Buffer.from(content, 'utf8'),
      fileName,
      'text/markdown'
    )
  }
};

// The webhook body, from Config ("Make folders" runs in between).
const input = $('Config').first().json.body;

const ignoredNameFragments = [
  '_transaction_polish_',
  '_mark_memo_',
  '_high_light_',
];

function shouldIgnoreFileName(name) {
  const value = String(name || '').toLowerCase();
  return ignoredNameFragments.some(fragment => value.includes(fragment));
}

// Applaud and n8n both run on the Docker host. With Settings → Webhook Outbound →
// Public URL set to http://docker.hayward.mx:44471 in Applaud, links already
// arrive with the right host and this changes nothing. Without it, Applaud
// sends its bind address (127.0.0.1); older deliveries may name the old host.
const APPLAUD_HOST = 'http://docker.hayward.mx';
function rewriteHost(url) {
  if (!url || typeof url !== 'string') return url;
  return url.replace(/^http:\/\/(?:127\.0\.0\.1|localhost|192\.168\.0\.117)(?=[:/]|$)/, APPLAUD_HOST);
}

// Links carry a read-only ticket for the recording's folder (?ticket=…); a link
// built from a file path below needs the same ticket or Applaud refuses it.
const folderTicket = (() => {
  try {
    return new URL(rewriteHost(input.http_urls?.summary || '')).searchParams.get('ticket') || '';
  } catch {
    return '';
  }
})();
function withTicket(url) {
  if (!url || !folderTicket || /[?&]ticket=/.test(url)) return url;
  return `${url}${url.includes('?') ? '&' : '?'}ticket=${encodeURIComponent(folderTicket)}`;
}

function sanitiseBaseName(name) {
  return String(name || 'Recording')
    .replace(/[\\/:*?\"<>|]/g, '-')
    .replace(/\s+/g, ' ')
    .replace(/[ .]+$/g, '')
    .trim();
}

function assetBaseName(name) {
  return String(name || '').split('/').pop() || '';
}

function extensionFromName(name, fallback = '') {
  const match = assetBaseName(name).match(/\.([a-z0-9]+)$/i);
  return match ? `.${match[1].toLowerCase()}` : fallback;
}

function firstPresent(...values) {
  return values.find(value => typeof value === 'string' && value.length > 0) || '';
}

function uniqueStrings(values) {
  return [...new Set(values.filter(value => typeof value === 'string' && value.length > 0))];
}

function mediaRootFromUrl(url) {
  const value = String(url || '').split('?')[0];
  const marker = '/media/';
  const index = value.indexOf(marker);
  return index === -1 ? '' : value.slice(0, index + marker.length);
}

function containingFolderFromUrl(url) {
  const value = String(url || '').split('?')[0];
  const index = value.lastIndexOf('/');
  return index === -1 ? '' : value.slice(0, index + 1);
}

function originFromUrl(url) {
  try {
    return new URL(url).origin;
  } catch {
    return '';
  }
}

function deriveAssetUrl(asset, summaryUrl) {
  if (asset.url) return rewriteHost(asset.url);

  const rewrittenSummaryUrl = rewriteHost(summaryUrl);
  const origin = originFromUrl(rewrittenSummaryUrl);
  const mediaRoot = mediaRootFromUrl(rewrittenSummaryUrl);
  const summaryFolder = containingFolderFromUrl(rewrittenSummaryUrl);

  for (const candidate of uniqueStrings([asset.path, asset.name])) {
    if (/^https?:\/\//i.test(candidate)) return rewriteHost(candidate);
    if (candidate.startsWith('/media/') && origin) return withTicket(`${origin}${candidate}`);
    if (candidate.includes('/')) {
      if (mediaRoot) return withTicket(`${mediaRoot}${candidate.replace(/^\/+/, '')}`);
      if (origin) return withTicket(`${origin}/media/${candidate.replace(/^\/+/, '')}`);
    }
    if (summaryFolder) return withTicket(`${summaryFolder}${candidate}`);
  }

  return '';
}

function londonPartsFromMs(ms) {
  const dt = new Date(ms);
  const parts = new Intl.DateTimeFormat('en-GB', {
    timeZone: 'Europe/London',
    year: 'numeric',
    month: '2-digit',
  }).formatToParts(dt);

  const year = parts.find(p => p.type === 'year')?.value;
  const month = parts.find(p => p.type === 'month')?.value;

  return { year, month };
}

function londonDateFromMs(ms) {
  const dt = new Date(ms);
  if (Number.isNaN(dt.getTime())) return '';
  const parts = new Intl.DateTimeFormat('en-GB', {
    timeZone: 'Europe/London',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  }).formatToParts(dt);
  const get = type => parts.find(p => p.type === type)?.value;
  return `${get('year')}-${get('month')}-${get('day')}`;
}

const { year, month } = londonPartsFromMs(input.recording.start_time_ms);
// Recording date (Europe/London) used for the front matter date field
const recordingDate = londonDateFromMs(input.recording.start_time_ms);
const baseName = sanitiseBaseName(input.recording.filename);
const targetRoot = `/data/applaud/${year}/${month}`;

// Obsidian vault copy (see "Copy to Vault"): YYYY/MM/{Summary,Transcript,Other},
// with summary images in Summary/images next to the summary that links to them.
const vaultRoot = String($('Config').first().json.vault_root || '/vault/003. Meetings').replace(/\/+$/, '');
const vaultMonth = `${vaultRoot}/${year}/${month}`;
const vaultDirs = {
  summary: `${vaultMonth}/Summary`,
  summaryImages: `${vaultMonth}/Summary/images`,
  transcript: `${vaultMonth}/Transcript`,
  other: `${vaultMonth}/Other`,
};

// If the recording filename itself is one of the excluded file types,
// do not create any FTP upload items for this webhook execution.
if (shouldIgnoreFileName(baseName)) {
  return [];
}

// Use Summary_*.md asset as main summary if present; fall back to http_urls.summary
const autoSummaryAsset = (input.http_urls.assets || []).find(asset => {
  if (asset.type !== 'markdown') return false;
  if (shouldIgnoreFileName(asset.name)) return false;

  const bn = assetBaseName(asset.name).toLowerCase();
  return bn.startsWith('summary_');
});

const summarySourceUrl = autoSummaryAsset
  ? rewriteHost(autoSummaryAsset.url)
  : rewriteHost(input.http_urls.summary);

const summaryDesiredFileName = `${baseName} - Summary.md`;
const summaryStem = summaryDesiredFileName.replace(/\.md$/i, '');
const summaryMarkdownText = firstPresent(
  input.content?.markdown_text,
  input.markdown_text,
  input.summary?.markdown_text
);
const summaryImageRelDir = 'Summary/images';
const summaryImageTargetDir = `${targetRoot}/${summaryImageRelDir}`;
const summaryImageMappings = [];

for (const asset of input.http_urls.assets || []) {
  if (shouldIgnoreFileName(asset.name)) continue;
  if (shouldIgnoreFileName(asset.path)) continue;
  if (shouldIgnoreFileName(asset.url)) continue;

  const assetIdentity = uniqueStrings([asset.name, asset.path, asset.url]).join(' ');
  const extension = extensionFromName(asset.name || asset.path || asset.url, '');
  const isPngAsset = extension === '.png' || /\.png(?:$|[?#])/i.test(assetIdentity);
  if (!isPngAsset) continue;

  const sourceCandidates = uniqueStrings([
    asset.name,
    asset.path,
    assetBaseName(asset.name),
    assetBaseName(asset.path),
    assetBaseName(asset.url),
  ]).sort((a, b) => b.length - a.length);

  const referencedSources = sourceCandidates.filter(candidate => summaryMarkdownText.includes(candidate));
  const looksLikeSummaryPoster = /summary_poster|card_[^/\\]+\.png/i.test(assetIdentity);

  // The downloaded Summary_*.md can contain the image link even when the webhook
  // payload does not expose markdown_text, so do not require a payload text match.
  if (referencedSources.length === 0 && !looksLikeSummaryPoster && summaryMarkdownText) continue;

  const rewriteSources = referencedSources.length > 0 ? referencedSources : sourceCandidates;
  if (rewriteSources.length === 0) continue;

  const desiredImageFileName = `${summaryStem}.png`;
  const relativeImagePath = `${summaryImageRelDir}/${desiredImageFileName}`;
  const sourceUrl = deriveAssetUrl(asset, summarySourceUrl);
  if (!sourceUrl) continue;

  summaryImageMappings.push({
    sourcePath: rewriteSources[0],
    rewriteSources,
    relativeImagePath,
    desiredImageFileName,
    sourceUrl,
  });
}

const items = [];

function pushItemIfAllowed(item) {
  const fileName = item?.json?.desiredFileName || '';
  const sourceUrl = item?.json?.sourceUrl || '';

  if (shouldIgnoreFileName(fileName)) return;
  if (shouldIgnoreFileName(sourceUrl)) return;

  items.push(item);
}

// Main summary only once
pushItemIfAllowed({
  json: {
    kind: 'downloadedMarkdown',
    sourceUrl: summarySourceUrl,
    targetDir: targetRoot,
    desiredFileName: summaryDesiredFileName,
    frontMatterType: 'summary',
    recordingDate,
    fixDividerSpacing: true,
    vaultDir: vaultDirs.summary,
    // NAS keeps the summary beside Summary/; in the vault it sits inside it.
    vaultRelinkImages: true,
    markdownImageRewrites: summaryImageMappings.flatMap(mapping =>
      (mapping.rewriteSources || [mapping.sourcePath]).map(source => ({
        source,
        replacement: `<${mapping.relativeImagePath}>`,
      }))
    ),
    recordingId: input.recording.id,
  }
});

for (const mapping of summaryImageMappings) {
  pushItemIfAllowed({
    json: {
      kind: 'downloadedImage',
      sourceUrl: mapping.sourceUrl,
      targetDir: summaryImageTargetDir,
      desiredFileName: mapping.desiredImageFileName,
      vaultDir: vaultDirs.summaryImages,
      recordingId: input.recording.id,
    }
  });
}

// Markdown assets except filtered duplicates
for (const asset of input.http_urls.assets || []) {
  if (asset.type !== 'markdown') continue;

  const bn = assetBaseName(asset.name).toLowerCase();

  // Ignore file types that should not be copied to the FTP server
  if (shouldIgnoreFileName(asset.name)) continue;
  if (shouldIgnoreFileName(asset.url)) continue;

  // Always skip summary.md
  if (bn === 'summary.md') continue;
  // Always skip outline duplicates
  if (bn.startsWith('outline__outline__')) continue;
  // Skip the Summary_*.md that was already used as the main summary
  if (autoSummaryAsset && asset === autoSummaryAsset) continue;
  // If no auto-summary was used, still skip any Summary_*.md assets
  if (!autoSummaryAsset && bn.startsWith('summary_')) continue;

  const rawAssetName = assetBaseName(asset.name);

  const safeAssetName = String(asset.name)
    .replace(/[\\/:*?\"<>|]/g, '-')
    .replace(/[ .]+$/g, '')
    .replace(/\s+/g, ' ')
    .trim();

  const desiredFileName = /^speech_summary/i.test(rawAssetName)
    ? `${baseName} - Speech Summary.md`
    : `${baseName} - ${safeAssetName}`;

  pushItemIfAllowed({
    json: {
      kind: 'downloadedMarkdown',
      sourceUrl: rewriteHost(asset.url),
      targetDir: targetRoot,
      desiredFileName,
      frontMatterType: /^speech_summary/i.test(rawAssetName) ? 'summary' : 'note',
      vaultDir: vaultDirs.other,
      recordingDate,
      recordingId: input.recording.id,
    }
  });
}

// Transcript generated from payload
pushItemIfAllowed({
  json: {
    kind: 'generatedTranscript',
    targetDir: targetRoot,
    desiredFileName: `${baseName} - Transcript.md`,
    frontMatterType: 'transcript',
    recordingDate,
    transcriptText: input.content?.transcript_text || '',
    vaultDir: vaultDirs.transcript,
    recordingId: input.recording.id,
  }
});

return items;

function buildFrontMatter(type, date) {
  return [
    '---',
    `type: ${type || 'note'}`,
    date ? `date: ${date}` : 'date:',
    'tags:',
    '  - plaud',
    'date_reviewed:',
    '---',
    '',
    '',
  ].join('\n');
}

function formatTranscript(text) {
  return String(text || '')
    .replace(/\r\n/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .replace(/\s*(\[\d{2}:\d{2}(?::\d{2})?\])/g, '\n$1')
    .replace(/^\n+/, '')
    .trim() + '\n';
}

const formatted =
  buildFrontMatter($json.frontMatterType || 'transcript', $json.recordingDate) +
  formatTranscript($json.transcriptText);
const fileName = $json.desiredFileName;
const filePath = `${$json.targetDir}/${fileName}`;

return [
  {
    json: {
      targetDir: $json.targetDir,
      desiredFileName: fileName,
      targetPath: filePath,
      vaultDir: $json.vaultDir || '',
      vaultRelinkImages: false,
    },
    binary: {
      data: await this.helpers.prepareBinaryData(
        Buffer.from(formatted, 'utf8'),
        fileName,
        'text/markdown'
      )
    }
  }
];

const upstream = $('Rewrite URLs').item.json;

const fileName = String(upstream.desiredFileName || 'image.png');
const targetDir = String(upstream.targetDir || '/data/applaud/Summary/images');
const filePath = `${targetDir}/${fileName}`;

const binary = $binary.data
  ? { ...$binary.data, fileName, mimeType: 'image/png' }
  : await this.helpers.prepareBinaryData(
      Buffer.from($json.data || $json.body || '', 'binary'),
      fileName,
      'image/png'
    );

return {
  json: {
    targetDir,
    desiredFileName: fileName,
    targetPath: filePath,
    vaultDir: upstream.vaultDir || '',
    vaultRelinkImages: upstream.vaultRelinkImages === true,
  },
  binary: { data: binary },
};

// Runs after each NAS write: the file just written there is the source for the
// vault copy. Paths go to the shell as base64 so spaces, quotes and $ are safe.
const source = String($json.targetPath || '');
const dir = String($json.vaultDir || '');
if (!source || !dir) {
  throw new Error(`No vault folder for ${source || 'this item'}; check Rewrite URLs sets vaultDir.`);
}
const fileName = source.split('/').pop();
const vaultPath = `${dir}/${fileName}`;
const b64 = value => Buffer.from(value, 'utf8').toString('base64');

return {
  json: {
    sourcePath: source,
    vaultPath,
    sourceB64: b64(source),
    vaultB64: b64(vaultPath),
    relinkImages: $json.vaultRelinkImages === true,
  },
};
